window.StrictDoc.search.nodesByMid = {"1":{"MID":"600f0c2e85a4466fa308fac6a74bb3f2","TITLE":"Patient monitor interface","_LINK":"1-Patient-monitor-interface"},"2":{"MID":"63d7239161b4487c9a3709903991b9cc","UID":"IRS001","TITLE":"attach","STATEMENT":"attach shall accept a Human and shall select the default limit profile for that patient's age.","_LINK":"IRS001"},"3":{"MID":"500139855e194d549020451fdada1e03","UID":"IRS002","TITLE":"start and stop","STATEMENT":"start shall begin monitoring when a patient is attached and shall reject a start when no patient is attached. stop shall end monitoring.","_LINK":"IRS002"},"4":{"MID":"aca7df2141204ec6b6a3efb52a3f8e14","UID":"IRS003","TITLE":"set_limits","STATEMENT":"set_limits shall accept an in-range AlarmLimits and shall raise LimitRejected without changing the limits already in effect when the command is out of range.","_LINK":"IRS003"},"5":{"MID":"9151513a913d46aaa0886bc2fe99da04","UID":"IRS004","TITLE":"vitals and alarms","STATEMENT":"vitals shall return a reading whose valid flag is true only while monitoring is running with a valid sensor. alarms shall return the active alarm set and shall return an empty set when monitoring is not running.","_LINK":"IRS004"},"6":{"MID":"c96c1a5eba95462ab919e1a5420a0cd2","TITLE":"Software units","_LINK":"1-Software-units"},"7":{"MID":"86282a7b5bb24cbdb77e3bd69529f521","UID":"SDD001","TITLE":"Human stimulus","STATEMENT":"Human and its patient subclasses shall hold the patient stimulus, including age and sensor validity, and shall not evaluate alarms.","_LINK":"SDD001"},"8":{"MID":"38efe0110fd74ca3be4c85a44eedf229","UID":"SDD002","TITLE":"AlarmLimits unit","STATEMENT":"AlarmLimits shall hold one limit profile and accept_limits shall decide whether a set_limits command is inside the allowed range.","_LINK":"SDD002"},"9":{"MID":"8ef4a14427364c8d9bdc785ea405341a","UID":"SDD003","TITLE":"AlarmEvaluator unit","STATEMENT":"AlarmEvaluator shall be a pure function from a patient and a limit profile to a set of alarms, including the inclusive-limit and sensor-fault rules.","_LINK":"SDD003"},"10":{"MID":"a40b08416ffc499bb6ea7ce8f4827582","UID":"SDD004","TITLE":"PatientMonitor unit","STATEMENT":"PatientMonitor shall own attach, start, stop, set_limits, vitals, and alarms, and shall keep the last accepted limits when a command is rejected.","_LINK":"SDD004"},"11":{"MID":"2def02eed4704d6eb36f66001df6263b","UID":"SDD005","TITLE":"No lower-class segregation","STATEMENT":"The pytest harness shall stay separate from the monitor package. No segregation is claimed for a lower software safety class, and every software item in this increment remains at Class C.","_LINK":"SDD005"},"12":{"MID":"9fedcd69046949cb944b9cbd7a6f7a3b","TITLE":"Planning for this mock increment","_LINK":"1-Planning-for-this-mock-increment"},"13":{"MID":"7e6000f4fd8b4fd2976ddb4c07b6eee3","UID":"SDP001","TITLE":"Confirmed software safety class","STATEMENT":"This mock shall be developed using the IEC 62304:2006+AMD1:2015 Class C activity set. The user confirmed Class C on 2026-10-20. These records do not constitute a claim of conformity.","_LINK":"SDP001"},"14":{"MID":"d2f3dab7b2234902bc51ab04224d6f2d","UID":"SDP002","TITLE":"Coding standard","STATEMENT":"Python in this increment shall follow PEP 8 and shall pass Ruff using the configuration in pyproject.toml.","_LINK":"SDP002"},"15":{"MID":"3998da78db184601868f17c72ac63793","UID":"SDP003","TITLE":"Verification order and record","STATEMENT":"Verification shall run unit tests, then integration tests, then software system tests. make test shall record the result in docs/pytest-report.html.","_LINK":"SDP003"},"16":{"MID":"785a6b7f94494baeb87ff314926f4b59","UID":"SDP004","TITLE":"SOUP identification","STATEMENT":"SOUP shall be identified as pytest 9.1.1 and pytest-html 4.2.0 from pytest-dev, Ruff 0.17.1 from Astral, and StrictDoc 0.30.1, with those versions pinned in uv.lock. The monitor package shall have no runtime dependency. Published-anomaly review is not completed, and this mock is not released medical-device software.","_LINK":"SDP004"},"17":{"MID":"a7e601534bd942509756a25a4a164a83","UID":"SDP005","TITLE":"Traceability","STATEMENT":"Traceability shall connect system requirements, software requirements, design, interfaces, test descriptions, and tests by UID relations and by Implements and Verifies comments.","_LINK":"SDP005"},"18":{"MID":"dc561da24abb48e9bde159cfff4f1746","UID":"SDP006","TITLE":"Resource acceptance not applicable","STATEMENT":"This design has no fixed-size buffers. Memory-overflow acceptance criteria do not apply to this increment.","_LINK":"SDP006"},"19":{"MID":"f8e5bf27ddf245d4a2dae757d8e7893a","TITLE":"Mock patient monitor system requirements","_LINK":"1-Mock-patient-monitor-system-requirements"},"20":{"MID":"151a8092d6e24cb0b0317ccd58ca78da","UID":"SRS001","TITLE":"Present vital signs","STATEMENT":"When monitoring is running and the sensor is valid, the monitor shall present the attached patient's heart rate in beats per minute, oxygen saturation in percent, systolic and diastolic blood pressure in millimetres of mercury, and temperature in degrees Celsius.","_LINK":"SRS001"},"21":{"MID":"9c6a9027894b4ddb9b9c53e4e8d379bc","UID":"SRS002","TITLE":"Alarm on out-of-limit vitals","STATEMENT":"The monitor shall raise an alarm when a valid vital sign is outside the limit profile for that patient's age.","_LINK":"SRS002"},"22":{"MID":"7feae6eb477344a796e37835643f9a20","UID":"SRS003","TITLE":"Sensor-fault alarm","STATEMENT":"The monitor shall raise a sensor-fault alarm when the measurement is invalid, and shall not raise a vital-sign alarm from an invalid measurement.","_LINK":"SRS003"},"23":{"MID":"33fd741c2f53401dbf112f1d644ae844","UID":"SRS004","TITLE":"Reject an out-of-range limit command","STATEMENT":"The monitor shall reject an alarm-limit command outside the allowed range and shall leave the limits already in effect unchanged.","_LINK":"SRS004"},"24":{"MID":"cecfbda4d1674f129dee04247da382fe","UID":"SRS005","TITLE":"Publish an HTML test report","STATEMENT":"The test harness shall run the software system tests and publish an HTML results report.","_LINK":"SRS005"},"25":{"MID":"e077849491874dfa89ff6837e65bdfea","TITLE":"Monitor behavior","_LINK":"1-Monitor-behavior"},"26":{"MID":"bba86e9041f6405ab8fe7ad8d11c1bcf","UID":"SSS001","TITLE":"Report five vital values","STATEMENT":"While monitoring is running and the sensor is valid, the monitor shall report the attached patient's heart rate, oxygen saturation, systolic pressure, diastolic pressure, and temperature unchanged.","_LINK":"SSS001"},"27":{"MID":"49dea5fd0777451594ba817e61f13eeb","UID":"SSS002","TITLE":"Select the limit profile by age","STATEMENT":"Age 18 years or older shall select the adult profile, and age under 18 years shall select the pediatric profile. Adult alarms are heart rate below 50 or above 120 bpm, SpO2 below 90 percent, systolic pressure above 160 mmHg, diastolic pressure above 100 mmHg, and temperature below 35.0 or above 38.0 degrees Celsius. Pediatric alarms are heart rate below 70 or above 160 bpm, SpO2 below 92 percent, systolic pressure above 120 mmHg, diastolic pressure above 80 mmHg, and temperature below 35.5 or above 38.0 degrees Celsius.","_LINK":"SSS002"},"28":{"MID":"b69b77abd4a341a7b8a8a87b98316047","UID":"SSS003","TITLE":"Inclusive limits","STATEMENT":"A vital sign equal to its limit shall not raise that vital's alarm.","_LINK":"SSS003"},"29":{"MID":"ee81ba5f0e654b9a80315e1af08efd52","UID":"SSS004","TITLE":"Idle and stopped monitor","STATEMENT":"Before start and after stop, the monitor shall report no alarms and shall not present vitals as valid. start with no patient attached shall be rejected.","_LINK":"SSS004"},"30":{"MID":"affc2f059ced4bc0aee2e86aa45a62c6","UID":"SSS005","TITLE":"Attach selects the default profile","STATEMENT":"attach shall store the patient and select that patient's default limit profile.","_LINK":"SSS005"},"31":{"MID":"4e26d35a38584919a71b8a8331807195","UID":"SSS006","TITLE":"Sensor fault risk control","STATEMENT":"When the sensor is invalid, the monitor shall raise only SENSOR_FAULT and shall not present vitals as valid.","_LINK":"SSS006"},"32":{"MID":"769c4495acf84cedb18b8b7c53e7b048","UID":"SSS007","TITLE":"Reject out-of-range limit command","STATEMENT":"set_limits shall reject a command whose heart-rate low limit is outside 20 through 200, whose heart-rate high limit is outside 30 through 250 or not strictly above the low limit, whose SpO2 low limit is outside 50 through 100, whose systolic high limit is outside 80 through 250, whose diastolic high limit is outside 40 through 150, or whose temperature limits are outside 30.0 through 43.0 or whose temperature high limit is not strictly above the low limit. A rejected command shall not be used for alarm evaluation, and the previously accepted limits shall remain.","_LINK":"SSS007"},"33":{"MID":"294e2f6cb9324b16b57e2ccd22ee5f94","TITLE":"Test harness","_LINK":"2-Test-harness"},"34":{"MID":"ba5c2890ab35470baf55f8ed75a487e6","UID":"SSS008","TITLE":"Function-scoped fixtures","STATEMENT":"The test harness shall provide function-scoped pytest fixtures named healthy_adult, tachycardic_adult, hypoxic_adult, hypertensive_adult, pediatric_patient, sensor_fault_patient, and patient_monitor, and each fixture shall return a new instance per test.","_LINK":"SSS008"},"35":{"MID":"d5acd8dc0dc54b66b8b13d5720c477b9","UID":"SSS009","TITLE":"HTML test report contents","STATEMENT":"make test shall write a self-contained pytest HTML report to docs/pytest-report.html, including software version 0.1.0, Python and package versions, the date, and the operating-system user as the person who ran the test.","_LINK":"SSS009"},"36":{"MID":"853e8700f0724bba95e6e734b0776474","TITLE":"Unit tests","_LINK":"1-Unit-tests"},"37":{"MID":"b37da416fa1f404eaf0161d3758bb37d","UID":"TD001","TITLE":"Age selects population","STATEMENT":"test_age_selects_population shall show that age 18 is not pediatric and age 17 is pediatric.","_LINK":"TD001"},"38":{"MID":"dbf2cf41c00048bb8f7ca370a08d7367","UID":"TD002","TITLE":"Patients inherit from Human","STATEMENT":"test_mock_patients_inherit_from_human shall show that each mock patient is a Human, the pediatric patient is age 8, and the sensor-fault patient has no numeric vitals.","_LINK":"TD002"},"39":{"MID":"f3a81ccfdd49469bbecaf2d2a25320b1","UID":"TD003","TITLE":"Default profiles accepted","STATEMENT":"test_default_profiles_are_accepted shall accept the adult and pediatric defaults and shall map age 18 to adult and age 17 to pediatric.","_LINK":"TD003"},"40":{"MID":"9e11a8ec4ffa4b7688d096d3fb47ef8b","UID":"TD004","TITLE":"Reject SpO2 above 100","STATEMENT":"test_rejects_spo2_above_100 shall reject an SpO2 low limit of 101.","_LINK":"TD004"},"41":{"MID":"cb683f5965c34694b8406c79f17bc0a2","UID":"TD005","TITLE":"Reject heart-rate order","STATEMENT":"test_rejects_heart_rate_high_not_above_low shall reject a heart-rate high limit that is not above the low limit.","_LINK":"TD005"},"42":{"MID":"49d0235d15264cf0b085fb2c3fb07dbf","UID":"TD006","TITLE":"Reject temperature order","STATEMENT":"test_rejects_temperature_high_not_above_low shall reject a temperature high limit that is not above the low limit.","_LINK":"TD006"},"43":{"MID":"d7cce7ffeabf4d599a27e63e7d7c1c3a","UID":"TD007","TITLE":"Equal to limit","STATEMENT":"test_equal_to_limit_does_not_alarm shall show that adult vitals equal to each limit do not alarm.","_LINK":"TD007"},"44":{"MID":"3c9f2cd4df394e71aa2ebc245c596b2b","UID":"TD008","TITLE":"One past the limit","STATEMENT":"test_one_past_adult_limits_alarms shall show that one step outside each adult limit raises that alarm.","_LINK":"TD008"},"45":{"MID":"a582b44379f847fd82bc24412d67d2fb","UID":"TD009","TITLE":"Pediatric limits differ","STATEMENT":"test_pediatric_limits_differ_from_adult shall show that SpO2 91 and heart rate 140 alarm differently on the adult and pediatric profiles.","_LINK":"TD009"},"46":{"MID":"7e30a6e2ad534427a6ce58bd0a120739","UID":"TD010","TITLE":"Sensor fault unit","STATEMENT":"test_sensor_fault_suppresses_vital_alarms shall show that an invalid sensor raises only SENSOR_FAULT.","_LINK":"TD010"},"47":{"MID":"9f4407b92de8424e97c9d47efe953777","TITLE":"Integration tests","_LINK":"2-Integration-tests"},"48":{"MID":"2a18b9ac8fde48f8a9740605a752ae45","UID":"TD011","TITLE":"Healthy adult integration","STATEMENT":"test_healthy_adult_reports_vitals_and_no_alarm shall present the healthy adult vitals unchanged, with the adult profile and no alarm.","_LINK":"TD011"},"49":{"MID":"6c8be376619c47848fbae8a644ddf327","UID":"TD012","TITLE":"Tachycardic adult integration","STATEMENT":"test_tachycardic_adult_heart_rate_alarm shall raise only HEART_RATE for the tachycardic adult.","_LINK":"TD012"},"50":{"MID":"3c44c6afeeca4204bdfc6afef2969c03","UID":"TD013","TITLE":"Hypoxic adult integration","STATEMENT":"test_hypoxic_adult_spo2_alarm shall raise only SPO2 for the hypoxic adult.","_LINK":"TD013"},"51":{"MID":"23afa354cd6a47f0ae6a53549b894e4c","UID":"TD014","TITLE":"Hypertensive adult integration","STATEMENT":"test_hypertensive_adult_blood_pressure_alarm shall raise only BLOOD_PRESSURE for the hypertensive adult.","_LINK":"TD014"},"52":{"MID":"980a827559dd48a0b73c8e1fd21a6e4d","UID":"TD015","TITLE":"Pediatric integration","STATEMENT":"test_pediatric_patient_uses_pediatric_profile shall select the pediatric profile and shall not alarm at heart rate 140.","_LINK":"TD015"},"53":{"MID":"d956a5c68beb41279a8c3bcf2dcb0433","UID":"TD016","TITLE":"Sensor fault integration","STATEMENT":"test_sensor_fault_patient_hides_vitals shall hide numeric vitals and raise only SENSOR_FAULT.","_LINK":"TD016"},"54":{"MID":"25d11c44bf22470281bfd983ab2bf8f5","UID":"TD017","TITLE":"Rejected limits integration","STATEMENT":"test_rejected_limits_leave_the_adult_profile shall keep the adult profile after a rejected command and shall not alarm the healthy adult.","_LINK":"TD017"},"55":{"MID":"fde5db8b6d8a414f8e13149583305a31","UID":"TD018","TITLE":"Idle and stopped integration","STATEMENT":"test_idle_and_stopped_monitor_has_no_alarms shall report no alarms before start and after stop, and shall alarm only while running.","_LINK":"TD018"},"56":{"MID":"82d7c7631f724e2a85ce83d1999329be","TITLE":"Software system tests","_LINK":"3-Software-system-tests"},"57":{"MID":"494ec69c6c474672b2e763e84ba63588","UID":"TD019","TITLE":"System vitals","STATEMENT":"test_system_reports_attached_vitals shall present the five healthy-adult vital values while monitoring is running.","_LINK":"TD019"},"58":{"MID":"ec8dbb2882b84f90946730df717b00ee","UID":"TD020","TITLE":"System profile by age","STATEMENT":"test_system_profile_follows_age shall apply the adult profile to the healthy adult and the pediatric profile to the pediatric patient.","_LINK":"TD020"},"59":{"MID":"46cab993d53f47cc9cdd873e5d867d7a","UID":"TD021","TITLE":"System boundary","STATEMENT":"test_system_boundary_value_does_not_alarm shall not alarm at heart rate 120 and shall alarm at heart rate 121 on the adult profile.","_LINK":"TD021"},"60":{"MID":"dc138884afc1499887e4e824142e55a2","UID":"TD022","TITLE":"System start and stop","STATEMENT":"test_system_start_and_stop shall reject start with no patient and shall clear alarms after stop.","_LINK":"TD022"},"61":{"MID":"6cb08cace293422abe12c67cb2208b27","UID":"TD023","TITLE":"System attach","STATEMENT":"test_system_attach_stores_patient_and_profile shall store the pediatric patient and select the pediatric profile.","_LINK":"TD023"},"62":{"MID":"fc534c7bbda549b197b79cba86e1e1b8","UID":"TD024","TITLE":"System sensor fault","STATEMENT":"test_system_sensor_fault shall raise only SENSOR_FAULT and shall not present vitals as valid.","_LINK":"TD024"},"63":{"MID":"307d9ce81e7f4cce8b8ea09595350496","UID":"TD025","TITLE":"System rejected command","STATEMENT":"test_system_rejects_out_of_range_command shall keep the previous limits and shall not alarm the healthy adult after a rejected command.","_LINK":"TD025"},"64":{"MID":"dab1621f11584a77b9256a08a7f1889b","UID":"TD026","TITLE":"Fixture scope","STATEMENT":"test_fixtures_are_function_scoped shall show that each required fixture is function scoped.","_LINK":"TD026"},"65":{"MID":"3a51a382ad344c4f9725f2c4fa389e09","UID":"TD027","TITLE":"HTML report configuration","STATEMENT":"test_html_report_path_and_metadata shall show that the report path is docs/pytest-report.html, that the HTML is self-contained, and that version 0.1.0, the device configuration, the tools, and the operator are recorded.","_LINK":"TD027"},"66":{"MID":"b4fdf19d08734204863ca22c07abf0bd","TITLE":"Verification plan","_LINK":"1-Verification-plan"},"67":{"MID":"97467234e6bc4989825d0e5e9a7893ff","UID":"TP001","TITLE":"Unit tests before integration","STATEMENT":"Unit tests in tests/unit shall be executed before integration tests. They shall cover limit acceptance, inclusive boundaries, profile selection, and sensor fault.","_LINK":"TP001"},"68":{"MID":"7dd84c0031504b698e3171db58edc7cb","UID":"TP002","TITLE":"Integration with each patient","STATEMENT":"Integration tests in tests/integration shall combine PatientMonitor with each patient fixture.","_LINK":"TP002"},"69":{"MID":"bd3d760f4247451694c6a88f2593fc9b","UID":"TP003","TITLE":"System coverage","STATEMENT":"System tests in tests/system shall cover every SSS requirement, including the risk controls SSS006 and SSS007.","_LINK":"TP003"},"70":{"MID":"a5888722013b4891a52074a3d25b803d","UID":"TP004","TITLE":"HTML record","STATEMENT":"The test record shall be docs/pytest-report.html produced by make test, and pytest shall collect tests/unit, then tests/integration, then tests/system.","_LINK":"TP004"}};
